import { graphql } from "gatsby";
import { GatsbyImage, getImage } from "gatsby-plugin-image";
import React, { useState } from "react";
import styled from "styled-components";
import Button from "../components/Button";
import ImageOverlay from "../components/ImageOverlay";
import InnerPage from "../components/InnerPage";
import Layout from "../components/Layout";
import Seo from "../components/Seo";
import StyledImage from "../components/StyledImage";
import Typography from "../components/Typography";
import FadeInOnScroll from "../components/FadeInOnScroll";
import text from "../text";
import convertImgArrToMap from "../utils/convertImgArrToMap";

const Section = styled.div`
  margin-bottom: 40px;
`;

const StyledHeader = styled(Typography)`
  margin-top: 20px;
  margin-bottom: 15px;
`;

const InfoText = styled(Typography)`
  margin-bottom: 20px;
  line-height: 1.6;
`;

const LinkContainer = styled.div`
  margin: 20px 0;
  display: flex;
  flex-wrap: wrap;
  gap: 15px;
`;

const StyledLink = styled.a`
  text-decoration: none;
  color: inherit;
`;

const PhotoGrid = styled.div`
  display: grid;
  grid-gap: 20px;
  margin-bottom: 20px;
  @media (min-width: 500px) {
    grid-template-columns: 1fr 1fr;
  }
  @media (min-width: 800px) {
    grid-template-columns: 1fr 1fr 1fr;
  }
  @media (min-width: 1000px) {
    grid-template-columns: 1fr 1fr 1fr 1fr;
  }
`;

const ImageContainer = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
`;

const ImageThumbnail = styled(StyledImage)`
  height: 0px;
  padding-bottom: 75%;
  cursor: pointer;
`;

const ImageCaption = styled(Typography)`
  margin-top: 10px;
  font-size: 0.9rem;
`;

const OverlayImage = styled(GatsbyImage)`
  align-self: center;
  margin-bottom: 20px;
`;

const FormContainer = styled.div`
  margin: 30px 0;
  border: ${({ theme }) => theme.decoration.border};
  box-shadow: ${({ theme }) => theme.decoration.boxShadow};
  border-radius: 8px;
  overflow: hidden;
  background: ${({ theme }) => theme.palette.background};
`;

const FormIframe = styled.iframe`
  width: 100%;
  min-height: 800px;
  border: none;
  display: block;
`;

const FormButtonContainer = styled.div`
  display: flex;
  gap: 15px;
  margin-top: 20px;
  flex-wrap: wrap;
`;

const GoogleFormLink = "https://docs.google.com/forms/d/e/1FAIpQLSeRiYDlxX0G1_Ytdc_YPKfPy6UnbQG3PJIBZRhczCze7HSWUQ/viewform";

// Template data - replace with your actual information
const externalPerformancesData = {
  info: "LNYF performs at various external events throughout the year. We showcase our cultural performances at community events, festivals, and other venues. [Replace this with your actual information about external performances.]",
  youtubeLink: text.links.youtube || "https://www.youtube.com/user/LNYF",
  photos: [
    // Template - replace with your actual photo data
    // { image: "external-1", caption: "External Performance 1" },
    // { image: "external-2", caption: "External Performance 2" },
    // { image: "external-3", caption: "External Performance 3" },
  ],
};

const ExternalPerformancesPage = ({ data }) => {
  const { imgData } = data;
  const { nodes } = imgData;
  const imgDataMap = convertImgArrToMap(nodes);
  const [open, setOpen] = useState(false);
  const [selectedPhoto, setSelectedPhoto] = useState(null);

  const handlePhotoClick = (photo) => {
    setSelectedPhoto(photo);
    setOpen(true);
  };

  return (
    <Layout>
      <Seo title="External Performances" />
      <InnerPage title="External Performances">
        <FadeInOnScroll direction="up" delay={0}>
          {/* Information Section */}
          <Section>
            <StyledHeader variant="h4">About External Performances</StyledHeader>
            <InfoText variant="p">
              {externalPerformancesData.info}
            </InfoText>
          </Section>

          {/* YouTube Channel Link */}
          <Section>
            <StyledHeader variant="h4">Watch Our Performances</StyledHeader>
            <LinkContainer>
              <StyledLink
                href={externalPerformancesData.youtubeLink}
                target="_blank"
                rel="noopener noreferrer"
              >
                <Button>Visit Our YouTube Channel</Button>
              </StyledLink>
            </LinkContainer>
          </Section>

          {/* Photo Gallery Section */}
          {externalPerformancesData.photos.length > 0 && (
            <Section>
              <StyledHeader variant="h4">Photo Gallery</StyledHeader>
              <PhotoGrid>
                {externalPerformancesData.photos.map((photo, i) => (
                  <FadeInOnScroll key={i} direction="up" delay={i * 50}>
                    <ImageContainer>
                      <ImageThumbnail
                        onClick={() => handlePhotoClick(photo)}
                        image={getImage(imgDataMap[photo.image])}
                        alt={photo.caption}
                        clickable="true"
                      />
                      {photo.caption && (
                        <ImageCaption variant="caption">
                          {photo.caption}
                        </ImageCaption>
                      )}
                    </ImageContainer>
                  </FadeInOnScroll>
                ))}
              </PhotoGrid>
            </Section>
          )}

          {/* Google Form Section */}
          <Section>
            <StyledHeader variant="h4">Request an External Performance</StyledHeader>
            <InfoText variant="p">
              Interested in having LNYF perform at your event? Fill out the form below or open it in a new tab.
            </InfoText>
            
            <FormButtonContainer>
              <StyledLink
                href={GoogleFormLink}
                target="_blank"
                rel="noopener noreferrer"
              >
                <Button>Open Form in New Tab</Button>
              </StyledLink>
            </FormButtonContainer>

            <FormContainer>
              <FormIframe
                src={GoogleFormLink}
                title="External Performance Request Form"
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                allowFullScreen
              />
            </FormContainer>
          </Section>
        </FadeInOnScroll>
      </InnerPage>

      {/* Image Overlay for Photo Gallery */}
      <ImageOverlay open={open} setOpen={setOpen}>
        {selectedPhoto && (
          <>
            <OverlayImage
              image={getImage(imgDataMap[selectedPhoto.image])}
              alt={selectedPhoto.caption}
              objectFit="contain"
            />
            {selectedPhoto.caption && (
              <Typography variant="p">Caption: {selectedPhoto.caption}</Typography>
            )}
          </>
        )}
      </ImageOverlay>
    </Layout>
  );
};

export default ExternalPerformancesPage;

export const query = graphql`
  query ExternalPerformancesPageQuery {
    imgData: allFile(
      filter: {
        sourceInstanceName: { eq: "images" }
        relativeDirectory: { eq: "external-performances" }
      }
    ) {
      nodes {
        childImageSharp {
          gatsbyImageData(placeholder: BLURRED, layout: CONSTRAINED)
        }
        name
      }
    }
  }
`;

